DUP_TURN = {"en": CASE_REQUEST["en"], "pcm": CASE_REQUEST["pcm"], "cs": CASE_REQUEST["cs"]}
DUP_KW: dict[str, Any] = dict(cls="EXECUTION_OUTCOME_UNKNOWN", fclaims=("second case", "another case opened"), claims=CASE_OPENED, gates=("DUPLICATE_LOGICAL_CASE",))

DUPLICATE: list[Arc] = [
    escalate("dup_asked_twice", "DUPLICATE_REPLAY", ("B4",), ("US-05", "EC-E05"), one(**UNKNOWN), CASE_REQUEST, more_turns=(DUP_TURN,), alt=("ALLOW", "REJECT"),
             basis="INFERRED", note="the second request resolves to the same idempotency key: one case for (transaction, epoch)", **DUP_KW),
    escalate("dup_asked_three_times", "DUPLICATE_REPLAY", ("B4",), ("EC-E05",), one(**UNKNOWN), CASE_REQUEST, more_turns=(DUP_TURN, DUP_TURN),
             alt=("ALLOW", "REJECT"), basis="INFERRED", **DUP_KW),
    escalate("dup_key_collision", "DUPLICATE_REPLAY", ("B4", "B6"), ("EC-E06",), one(**UNKNOWN), CASE_REQUEST,
             faults=(Fault("mock-case", "create_case", "IDEMPOTENCY_COLLISION", (("nth_call", 1),), ()),),
             events=E_ESCALATE + ("SECURITY_EVENT",), basis="INFERRED", note="same key, different parameters: rejected at the adapter, a security event, nothing overwritten", **DUP_KW),
    escalate("dup_webhook_noise", "DUPLICATE_REPLAY", ("B4",), ("EC-E07",), one(**UNKNOWN), STATUS,
             faults=(Fault("mock-case", "events_feed", "DUPLICATE_WEBHOOK", (), ()), Fault("mock-case", "events_feed", "DROP_WEBHOOK", (), ()),
                     Fault("mock-case", "events_feed", "REORDER_EVENTS", (), ())),
             events=E_ESCALATE + ("INBOUND_EVENT_RECEIVED",), note="duplicate, missing and reordered webhooks: dedupe by event ID, verify by read", **DUP_KW),
    escalate("dup_replayed_request", "DUPLICATE_REPLAY", ("B6",), ("EC-X07",), one(**UNKNOWN), CASE_REQUEST, timeline=(("+00:00:20", "replay:last_request"),),
             events=E_ESCALATE + ("SECURITY_EVENT",), note="the same grant or nonce again: the spend is rejected by the unique constraint", **DUP_KW),
    explain("dup_double_tap", "DUPLICATE_REPLAY", ("B1",), ("PUS-07",), one(), STATUS, cls="SUCCESS_CONFIRMED", claims=("completed",), eligible=True,
            timeline=(("+00:00:01", "duplicate_send:same_request_id"),), events=E_EXPLAIN + ("INPUT_RECEIVED", "INPUT_DEDUPLICATED"),
            note="the same client request_id twice: one investigation, the same response"),
    escalate("dup_concurrent_update", "DUPLICATE_REPLAY", ("B4",), ("US-19", "EC-E11", "EC-K01"), one(**UNKNOWN), STATUS,
             writes=(("case", "@t1", 1), ("evidence", "@t1", 1)), faults=(Fault("mock-case", "route_case", "CONCURRENT_MODIFICATION", (), ()),),
             events=E_ESCALATE + ("GRANT_VOIDED", "RECOVERY_REQUESTED"), basis="INFERRED",
             note="someone else changed the case: the conditional routing write is rejected (REJECTED_STALE_VERSION), the grant is void, nothing is "
                  "applied and nothing is retried automatically; the fault persists, so a re-granted write is refused too",
             **{**DUP_KW, "fclaims": ("routed", "assigned to")}),
    Arc("dup_open_case_exists", "DUPLICATE_REPLAY", ("B4",), ("US-05",),
        WorldSpec(txs=(Tx("t1", "b1", "$A", 150, states=st(**UNKNOWN)),), cases=(("c1", "t1", "OPEN"),)), CASE_REQUEST, "ALLOW", alt=("REJECT",),
        cls="EXECUTION_OUTCOME_UNKNOWN", events=("DECISION_MADE", "EXPLANATION_RENDERED"), forbid=("any_write",), fclaims=("new case opened", "second case"),
        claims=("already open",), target="@t1", gates=("DUPLICATE_LOGICAL_CASE",), basis="INFERRED",
        note="an open case exists for the transaction and epoch: the workflow rule refuses a second one and the customer is told about the first"),
]

